#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing grader disk-cache (perfect reproducibility)..."
decode "fix_grader_cache.py" << 'B64EOF'

B64EOF
python fix_grader_cache.py && rm fix_grader_cache.py
echo "Done. Verify 3 fresh passes give identical counts."